from pathlib import Path
import json
p=Path(__file__).parent;f=json.loads((p/'facts/inputs.json').read_text());s=(p/'report.md').read_text()
r=dict(ticker='TRMD',as_of='2026-11-04',research_cutoff=f['research_cutoff'],scanner_date=f['scanner_date'],scanner_price=f['scanner_price'],price=f['price_reference'],price_date=f['price_date'],certified_close=None,price_note=f['price_note'],research_status='Partial factual research; independent audit completed for partial scope',bear=None,base=None,bull=None,buy_ceiling=None,owner_fcf=None,equity_bridge=None,bridge_certified=False,wacc_calibrated=False,approved_entry=False,stage35_approved=False,latestCompleted=False,decision_es='Investigación parcial: normalizar ciclo y reposición de flota antes de valorar; no entrada.',decision_en='Partial research: normalize the freight cycle and fleet replacement before valuation; no entry.',publication_note='Issuer NAV and its sensitivities are not intrinsic values or a fair-value range. Postquarter dividend, JV funding and leaseback repurchases remain distinct. All aggregate valuation fields are null.')
for k,title in [('pros_es','Pros ES'),('cons_es','Contras ES'),('pros_en','Pros EN'),('cons_en','Cons EN')]:r[k]=[x[2:] for x in s.split('### '+title+'\n')[1].split('\n#')[0].strip().splitlines() if x.startswith('- ')]
(p/'publication.json').write_text(json.dumps(r,indent=2,ensure_ascii=False)+'\n')
